import {DEFAULTS,normalizeQuality} from './world.js';
export const QUALITY_REVIEW_LOCK=true;
export const QUALITY_IDS=['viral-escape','viral-multiply','viral-last'];
export function mountQualityControls(root,onChange){let mode='escape',cached={...DEFAULTS};const fields={};root.innerHTML='<h3>品質版の物理設定</h3><p class="micro">検証対象は既存の3作品です。旧「詳細カスタマイズ」は別の旧エンジンです。品質版はこの設定を使い、1本ずつ確認してください。BGMなし・30秒まで。</p>';
 const form=document.createElement('div');form.className='fields';root.append(form);
 const specs=[['balls','初期ボール数',1,16,1],['rings','リング数（Ring Escape）',1,5,1],['gap','隙間の幅（rad）',.4,1.7,.05],['phase','隙間の初期位置（rad）',-3.14,3.14,.05],['rotation','リング回転速度（rad/s）',0,1.5,.05],['speed','初速（px/s）',80,650,5],['gravity','重力（px/s²）',0,350,5],['restitution','反発係数',.8,1,.01],['maxBalls','増殖の上限',2,48,1]];
 for(const [key,label,min,max,step] of specs){const wrap=document.createElement('label');wrap.textContent=label;const input=document.createElement('input');input.type='number';input.name='quality-'+key;input.min=min;input.max=max;input.step=key==='phase'?'any':step;input.value=DEFAULTS[key];input.onchange=()=>{try{normalizeQuality(values());input.setCustomValidity('');onChange()}catch(e){input.setCustomValidity(e.message);input.reportValidity();onChange()}};wrap.append(input);form.append(wrap);fields[key]=input}
 for(const [key,label,options] of [['direction','回転方向',[['alternate','交互'],['clockwise','時計回り'],['counterclockwise','反時計回り']]],['multiplyWhen','増殖条件',[['hit','衝突'],['gate','ゲート通過']]],['eliminateWhen','脱落条件',[['escape','リング外へ脱出'],['hazard','障害物への接触']]],['obstacles','障害物配置',[['chicane','互い違い'],['spinner','回転バー']]],['ending','結末表示',[['winner','勝者'],['podium','勝者と脱落順']]]]){const wrap=document.createElement('label');wrap.textContent=label;const select=document.createElement('select');select.name='quality-'+key;for(const [value,text] of options)select.add(new Option(text,value));select.value=DEFAULTS[key];select.onchange=onChange;wrap.append(select);form.append(wrap);fields[key]=select}
 function values(){return Object.fromEntries(Object.entries(fields).map(([k,input])=>[k,input.type==='number'?Number(input.value):input.value]))}
 function load(value){const c=normalizeQuality(value);cached=c;for(const [key,field] of Object.entries(fields)){field.value=c[key];field.setCustomValidity('')}}
 return {getValue:()=>{try{cached=normalizeQuality(values())}catch{}return {...cached}},isValid:()=>{try{normalizeQuality(values());return Object.values(fields).every(f=>f.validity.valid)}catch{return false}},load,setMode(id){const next=id.replace('viral-','');if(next!==mode){mode=next;load({...DEFAULTS,balls:mode==='last'?12:1,gap:mode==='last'?1.45:DEFAULTS.gap});fields.rings.disabled=mode!=='escape';fields.maxBalls.disabled=mode!=='multiply';fields.multiplyWhen.disabled=mode!=='multiply';for(const k of ['eliminateWhen','obstacles','ending'])fields[k].disabled=mode!=='last'}},setActive(enabled){root.hidden=!enabled}};
}
